//import { FaClipboardList } from "react-icons/fa";
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { useState, useEffect } from 'react';
import { FiMenu, FiLogOut } from 'react-icons/fi';
import { FaStore, FaClipboardList, FaUserAlt } from 'react-icons/fa';
import logo from '../assets/logo.png';

function SidebarLayoutLoja({ user, children }) {
  const [open, setOpen] = useState(true);
  const navigate = useNavigate();
  const location = useLocation();

  useEffect(() => {
    if (!user) {
      navigate('/');
    }
  }, [user, navigate]);

  if (!user) return null;

  const handleLogout = () => navigate('/');

  const isActive = (path) => location.pathname === path;

  return (
    <div className="flex min-h-screen">
      <aside
        className={`bg-green-900 text-white transition-all ${
          open ? 
          'w-64' : 
          'w-16'
          } p-4 flex flex-col justify-between`}
      >
        <div>
          <button
            onClick={() => setOpen(!open)}
            className="mb-4 text-2xl p-2 hover:bg-green-800 rounded"
          >
            <FiMenu />
          </button>

          {open && (
            <div className="mb-6 flex flex-col items-center">
              <img src={logo} alt="Leo Madeiras" className="w-20 h-auto mb-2" />
              <h2 className="text-center font-bold text-xl">Olá, {user.name}</h2>
              <p className="text-center text-sm opacity-75">Loja</p>
            </div>
          )}

          <nav className="space-y-2">
            <Link
              to="/loja/coletas"
              className={`flex items-center p-2 rounded ${isActive('/loja/coletas')
                  ? 'bg-yellow-500 text-black'
                  : 'hover:bg-green-800'
                }`}
            >
              <FaClipboardList className="mr-2" /> {open && 'Coletas'}
            </Link>

            <Link
              to="/loja/lista-coletas"
              className={`flex items-center gap-2 p-2 rounded hover:bg-green-800 ${isActive("/loja/lista-coletas") ? "bg-green-800" : ""}`}
            >
              <FaClipboardList className="mr-2" /> {open && 'Lista de Coletas'}
            </Link>

            <Link
              to="/loja/dados-loja"
              className={`flex items-center p-2 rounded ${isActive('/loja/dados-loja')
                  ? 'bg-yellow-500 text-black'
                  : 'hover:bg-green-800'
                }`}
            >
              <FaStore className="mr-2" /> {open && 'Dados da Loja'}
            </Link>

            <Link
              to="/loja/carreteiros"
              className={`flex items-center p-2 rounded ${isActive('/loja/carreteiros')
                  ? 'bg-yellow-500 text-black'
                  : 'hover:bg-green-800'
                }`}
            >
              <FaUserAlt className="mr-2" /> {open && 'Carreteiros'}
            </Link>
            <button
              onClick={handleLogout}
              className="flex items-center p-2 hover:bg-green-800 rounded mt-4"
            >
              <FiLogOut className="mr-2" /> {open && 'Sair'}
            </button>

          </nav>
        </div>


      </aside>

      <main className="flex-1 p-4 bg-gray-100 overflow-auto">{children}</main>
    </div>
  );
}

export default SidebarLayoutLoja;
