
import IndexURI from '../api/index';
import { buscarDadosPrivado, buscarDadosPublico } from '../api/ApiBaseService';
//import { Usuario, UsuarioAPI } from '../models/Usuario';
import { SeVazioUndefinedOuNulo } from '../utilities/Utilidades';
import { errorMessage } from '../components/Mensagem';

export class TransportadorServico {

    static async PreCadastroTransportador({ precadastro }) {
        let resposta;

        try {

            resposta = await buscarDadosPublico(
                IndexURI().pre_cadastro_transportador,
                'POST',
                precadastro
            );


        } catch (error) {
            console.log(error);
            resposta.erros = error;
            resposta.sucesso = false;
        }
        finally {
            return resposta;
        }
    }

    static async ImportarConhecimentos({ files }) {
        let resposta;
        let token = localStorage.getItem('token');

        try {
            resposta = await buscarDadosPrivado(
                IndexURI().importar_cte,
                'POST',
                files,
                token
            );


        } catch (error) {
            console.log(error);
            resposta.erros = error;
            resposta.sucesso = false;
        }
        finally {
            return resposta;
        }
    }

    static async EditarTransportador(dadosTransportador) {
        let resposta;
        let token = localStorage.getItem('token');

        try {
            resposta = await buscarDadosPrivado(
                IndexURI().editar_transportador,
                'PUT',
                dadosTransportador,
                token
            );

            return resposta;

        } catch (error) {
            console.log(error);
            resposta.erros = error;
            resposta.sucesso = false;
        }
        finally {
            return resposta;
        }
    }

    static async BuscarTransportadorPorCNPJ(cnpj) {
        let resposta;
        let token = localStorage.getItem('token');

        try {
            resposta = await buscarDadosPrivado(
                IndexURI().buscar_transportador_por_cnpj({ cnpj }),
                'GET',
                null,
                token
            );


        } catch (error) {
            console.log(error);
            resposta.erros = error;
            resposta.sucesso = false;
        }
        finally {
            return resposta;

        }
    }

}
