import { useState, useEffect } from "react";
import OrdemDeColetaPrint from "../../components/OrdemDeColetaPrint";

export default function Coletas({ user }) {
  const [cepOrigem, setCepOrigem] = useState("");
  const [cepDestino, setCepDestino] = useState("");
  const [coletaId, setColetaId] = useState(null);
  const [enderecoOrigem, setEnderecoOrigem] = useState({ rua: "", numero: "", bairro: "", cidade: "", uf: "" });
  const [enderecoDestino, setEnderecoDestino] = useState({ rua: "", numero: "", bairro: "", cidade: "", uf: "" });
  const [showNotaModal, setShowNotaModal] = useState(false);
  const [notas, setNotas] = useState([]);
  const [filtroNota, setFiltroNota] = useState("");
  const [notasSelecionadas, setNotasSelecionadas] = useState([]);
  const [showOrdemModal, setShowOrdemModal] = useState(false);
  const [dadosOrdem, setDadosOrdem] = useState(null);

  const [remetenteCNPJ, setRemetenteCNPJ] = useState("");
  const [remetenteRazao, setRemetenteRazao] = useState("");
  const [destinatarioCNPJ, setDestinatarioCNPJ] = useState("");
  const [destinatarioRazao, setDestinatarioRazao] = useState("");

  const [motivo, setMotivo] = useState("");
  const [carreteiro, setCarreteiro] = useState("");
  const [valorFrete, setValorFrete] = useState("");
  const [hora, setHora] = useState("");

  const handleConfirmar = () => {
    if (notasSelecionadas.length === 0) {
      alert("É necessário vincular ao menos uma Nota Fiscal antes de confirmar a ordem.");
      return;
    }
    const numero = Math.floor(100000 + Math.random() * 900000);
    setColetaId(numero);
    const dados = {
      numero,
      dataSolicitacao: new Date().toLocaleDateString(),
      horaSolicitacao: hora || new Date().toLocaleTimeString(),
      horario: hora || "--:--",
      empresa: {
        nome: user.name,
        endereco: enderecoOrigem.rua,
        numero: enderecoOrigem.numero,
        municipio: enderecoOrigem.cidade,
        cep: cepOrigem,
        fone: "(11) 1111-1111",
        fax: "(11) 2222-2222",
        cnpj: "00.000.000/0000-00",
        uf: enderecoOrigem.uf,
      },
      remetente: {
        cnpj: remetenteCNPJ,
        nome: remetenteRazao,
        endereco: enderecoOrigem.rua,
        numero: enderecoOrigem.numero,
        cidade: enderecoOrigem.cidade,
        bairro: enderecoOrigem.bairro,
        estado: enderecoOrigem.uf,
      },
      destinatario: {
        cnpj: destinatarioCNPJ,
        nome: destinatarioRazao,
        endereco: enderecoDestino.rua,
        numero: enderecoDestino.numero,
        municipio: enderecoDestino.cidade,
        bairro: enderecoDestino.bairro,
        estado: enderecoDestino.uf,
      },
      motorista: carreteiro,
      veiculo: "",
      placa: "",
      cnh: "",
      peso: "",
      volume: "",
      valor: valorFrete,
      produto: "",
      observacao: "",
      motivo,
      notasVinculadas: notasSelecionadas,
    };
    setDadosOrdem(dados);
    setShowOrdemModal(true);
  };

  const buscarEndereco = async (cep, tipo) => {
    try {
      const res = await fetch(`https://viacep.com.br/ws/${cep}/json/`);
      const data = await res.json();
      if (data.erro) return;
      const endereco = {
        rua: data.logradouro,
        numero: "",
        bairro: data.bairro,
        cidade: data.localidade,
        uf: data.uf,
      };
      if (tipo === "origem") setEnderecoOrigem(endereco);
      if (tipo === "destino") setEnderecoDestino(endereco);
    } catch (err) {
      console.error("Erro ao buscar CEP:", err);
    }
  };

  useEffect(() => {
    if (cepOrigem.length === 8) buscarEndereco(cepOrigem, "origem");
  }, [cepOrigem]);

  useEffect(() => {
    if (cepDestino.length === 8) buscarEndereco(cepDestino, "destino");
  }, [cepDestino]);

  const handlePesquisarNotas = () => {
    const resultados = [
      { dtEmissao: "2025-06-20", nf: "123456", pedido: "P001", remetente: "Empresa A", peso: "100kg", valor: "R$ 500" },
      { dtEmissao: "2025-06-22", nf: "789012", pedido: "P002", remetente: "Empresa B", peso: "250kg", valor: "R$ 1300" },
      { dtEmissao: "2025-06-23", nf: "345678", pedido: "P003", remetente: "Empresa C", peso: "180kg", valor: "R$ 750" },
    ];
    const filtro = filtroNota.trim().toLowerCase();
    const resultado = resultados.filter(
      n => n.nf.toLowerCase().includes(filtro) || n.pedido.toLowerCase().includes(filtro)
    );
    if (resultado.length === 0) {
      const desejaVincular = window.confirm("Nota não localizada. Deseja vincular este número à Ordem de Serviço?");
      if (desejaVincular) {
        setNotasSelecionadas(prev => [...prev, { dtEmissao: "-", nf: filtroNota, pedido: "-", remetente: "Manual", peso: "-", valor: "-" }]);
        setShowNotaModal(false);
        setNotas([]);
      }
    } else {
      setNotas(resultado);
    }
  };

  const selecionarNota = (nota) => {
    const jaSelecionada = notasSelecionadas.some(n => n.nf === nota.nf);
    if (!jaSelecionada) {
      setNotasSelecionadas(prev => [...prev, nota]);
      setNotas([]);
      setFiltroNota("");
    } else {
      alert("Esta nota já está vinculada.");
    }
  };

  const removerNota = (nf) => {
    setNotasSelecionadas(prev => prev.filter(nota => nota.nf !== nf));
  };

  const handleRemetenteKeyDown = (e) => {
    if (e.key === "Enter") {
      if (remetenteCNPJ.toLowerCase() === "leo madeiras") {
        setRemetenteRazao("Leo Madeiras CD");
        setRemetenteCNPJ("61.069.373/0061-44");
      }
    }
  };

  const handleDestinatarioKeyDown = (e) => {
    if (e.key === "Enter") {
      if (destinatarioCNPJ.toLowerCase() === "mantran") {
        setDestinatarioRazao("Mantran Tecnologias");
        setDestinatarioCNPJ("00.109.424/0001-99");
      }
    }
  };





  return (
    <div className="p-6 space-y-6">
      <h1 className="text-2xl font-bold">Ordem de Serviço</h1>

      {/* Card: Dados da Coleta */}
      <div className="bg-white p-4 rounded-xl shadow space-y-6">
        <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
          <div>
            <label className="block font-medium mb-1">Data Solicitação</label>
            <input
              type="date"
              defaultValue={new Date().toISOString().split("T")[0]}
              className="w-full border px-3 py-2 rounded"
              readOnly
            />
          </div>
          <div>
            <label className="block font-medium mb-1">Hora</label>
            <input
              type="time"
              value={hora}
              onChange={(e) => setHora(e.target.value)}
              className="w-full border px-3 py-2 rounded"
            />
          </div>
          <div>
            <label className="block font-medium mb-1">Motivo</label>
            <select
              value={motivo}
              onChange={(e) => setMotivo(e.target.value)}
              className="w-full border px-3 py-2 rounded"
            >
              <option value="">Selecione</option>
              <option value="Devolução">Devolução</option>
              <option value="Reentrega">Reentrega</option>
              <option value="Entrega">Entrega</option>
              <option value="Coleta">Coleta</option>
            </select>
          </div>
          <div>
            <label className="block font-medium mb-1">Carreteiro</label>
            <select
              value={carreteiro}
              onChange={(e) => setCarreteiro(e.target.value)}
              className="w-full border px-3 py-2 rounded"
            >
              <option value="">Selecione</option>
              <option>Fernando</option>
              <option>Carlos</option>
              <option>João</option>
            </select>
          </div>
          <div>
            <label className="block font-medium mb-1">Valor Frete</label>
            <input
              type="text"
              value={valorFrete}
              onChange={(e) => setValorFrete(e.target.value)}
              className="w-full border px-3 py-2 rounded"
              placeholder="R$"
            />
          </div>
        </div>

        <div className="space-y-1">
          <label className="block font-medium mb-1">Remetente</label>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <input
              type="text"
              value={remetenteCNPJ}
              onChange={(e) => setRemetenteCNPJ(e.target.value)}
              onKeyDown={handleRemetenteKeyDown}
              className="w-full border px-3 py-2 rounded"
              placeholder="Digite o CNPJ ou nome"
            />
            <input
              type="text"
              value={remetenteRazao}
              readOnly
              className="w-full border px-3 py-2 rounded bg-gray-100"
              placeholder="Razão Social"
            />
          </div>
        </div>

        <button
          className="bg-blue-600 text-white px-3 py-1 rounded hover:bg-blue-700 text-sm"
          onClick={() => setShowNotaModal(true)}
          style={{ width: "120px", height: "32px" }}
        >
          Nota Fiscais
        </button>
      </div>

      {/* Card: Local da Coleta */}
      <div className="bg-white p-4 rounded-xl shadow space-y-4">
        <h2 className="text-lg font-semibold">Local da Coleta</h2>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div>
            <label className="block font-medium mb-1">CEP</label>
            <input
              type="text"
              value={cepOrigem}
              onChange={(e) => setCepOrigem(e.target.value)}
              className="w-full border px-3 py-2 rounded"
            />
          </div>
          <div>
            <label className="block font-medium mb-1">Rua</label>
            <input type="text" value={enderecoOrigem.rua} className="w-full border px-3 py-2 rounded" readOnly />
          </div>
          <div>
            <label className="block font-medium mb-1">Nº</label>
            <input
              type="text"
              value={enderecoOrigem.numero}
              onChange={(e) => setEnderecoOrigem(prev => ({ ...prev, numero: e.target.value }))}
              className="w-full border px-3 py-2 rounded"
              placeholder="Número"
            />
          </div>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mt-2">
          <div>
            <label className="block font-medium mb-1">Bairro</label>
            <input type="text" value={enderecoOrigem.bairro} className="w-full border px-3 py-2 rounded" readOnly />
          </div>
          <div>
            <label className="block font-medium mb-1">Cidade</label>
            <input type="text" value={enderecoOrigem.cidade} className="w-full border px-3 py-2 rounded" readOnly />
          </div>
          <div>
            <label className="block font-medium mb-1">UF</label>
            <input type="text" value={enderecoOrigem.uf} className="w-full border px-3 py-2 rounded" readOnly />
          </div>
        </div>
      </div>

      {/* Card: Destinatário */}
      <div className="bg-white p-4 rounded-xl shadow space-y-4">
        <h2 className="text-lg font-semibold">Destinatário</h2>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className="md:col-span-3 grid grid-cols-2 gap-4">
            <input
              type="text"
              value={destinatarioCNPJ}
              onChange={(e) => setDestinatarioCNPJ(e.target.value)}
              onKeyDown={handleDestinatarioKeyDown}
              className="w-full border px-3 py-2 rounded"
              placeholder="Digite o CNPJ ou nome"
            />
            <input
              type="text"
              value={destinatarioRazao}
              readOnly
              className="w-full border px-3 py-2 rounded bg-gray-100"
              placeholder="Razão Social"
            />
          </div>
          <div>
            <label className="block font-medium mb-1">CEP</label>
            <input
              type="text"
              value={cepDestino}
              onChange={(e) => setCepDestino(e.target.value)}
              className="w-full border px-3 py-2 rounded"
            />
          </div>
          <div>
            <label className="block font-medium mb-1">Rua</label>
            <input type="text" value={enderecoDestino.rua} className="w-full border px-3 py-2 rounded" readOnly />
          </div>
          <div>
            <label className="block font-medium mb-1">Nº</label>
            <input
              type="text"
              value={enderecoDestino.numero}
              onChange={(e) => setEnderecoDestino(prev => ({ ...prev, numero: e.target.value }))}
              className="w-full border px-3 py-2 rounded"
              placeholder="Número"
            />
          </div>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mt-2">
          <div>
            <label className="block font-medium mb-1">Bairro</label>
            <input type="text" value={enderecoDestino.bairro} className="w-full border px-3 py-2 rounded" readOnly />
          </div>
          <div>
            <label className="block font-medium mb-1">Cidade</label>
            <input type="text" value={enderecoDestino.cidade} className="w-full border px-3 py-2 rounded" readOnly />
          </div>
          <div>
            <label className="block font-medium mb-1">UF</label>
            <input type="text" value={enderecoDestino.uf} className="w-full border px-3 py-2 rounded" readOnly />
          </div>
        </div>
      </div>

      {/* Botão para abrir modal de notas */}




      {/* Botão Confirmar */}
      <div className="text-right mt-6">
        <button
          onClick={handleConfirmar}
          className="bg-green-600 text-white px-6 py-2 rounded hover:bg-green-700"
        >
          Confirmar
        </button>
      </div>

      {/* Modal de notas */}
      {showNotaModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white p-6 rounded-xl w-full max-w-3xl shadow-xl space-y-4">
            <h2 className="text-xl font-semibold">Pesquisar Nota Fiscal</h2>
            <input
              type="text"
              placeholder="NR Pedido ou NR NF"
              value={filtroNota}
              onChange={(e) => setFiltroNota(e.target.value)}
              className="w-full border px-3 py-2 rounded"
            />
            <button
              onClick={handlePesquisarNotas}
              className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700"
            >
              Pesquisar
            </button>
            {notas.length > 0 && (
              <table className="w-full mt-4 border text-sm">
                <thead>
                  <tr className="bg-gray-100">
                    <th className="p-2 border">DT Emissão</th>
                    <th className="p-2 border">NR NF</th>
                    <th className="p-2 border">NR Pedido</th>
                    <th className="p-2 border">Remetente</th>
                    <th className="p-2 border">Peso</th>
                    <th className="p-2 border">Valor NF</th>
                    <th className="p-2 border">Ação</th>
                  </tr>
                </thead>
                <tbody>
                  {notas.map((nota, idx) => (
                    <tr key={idx} className="text-center">
                      <td className="p-2 border">{nota.dtEmissao}</td>
                      <td className="p-2 border">{nota.nf}</td>
                      <td className="p-2 border">{nota.pedido}</td>
                      <td className="p-2 border">{nota.remetente}</td>
                      <td className="p-2 border">{nota.peso}</td>
                      <td className="p-2 border">{nota.valor}</td>
                      <td className="p-2 border">
                        <button
                          onClick={() => selecionarNota(nota)}
                          className="bg-green-600 text-white px-2 py-1 rounded hover:bg-green-700 text-xs"
                        >
                          Selecionar
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
			
	{notasSelecionadas.length > 0 && (
  <div className="mt-6">
    <h3 className="text-lg font-semibold mb-2">Notas Selecionadas:</h3>
    <table className="w-full border text-sm">
      <thead>
        <tr className="bg-gray-200">
          <th className="p-2 border">
            <input
              type="checkbox"
              checked={
                notasSelecionadas.every(nota => nota.checked)
              }
              onChange={(e) => {
                const checked = e.target.checked;
                setNotasSelecionadas(prev =>
                  prev.map(nota => ({ ...nota, checked }))
                );
              }}
            />
          </th>
          <th className="p-2 border">NR NF</th>
          <th className="p-2 border">Remetente</th>
          <th className="p-2 border">Pedido</th>
          <th className="p-2 border">Peso</th>
          <th className="p-2 border">Valor</th>
        </tr>
      </thead>
      <tbody>
        {notasSelecionadas.map((nota, idx) => (
          <tr key={idx} className="text-center">
            <td className="p-2 border">
              <input
                type="checkbox"
                checked={!!nota.checked}
                onChange={(e) => {
                  const updated = [...notasSelecionadas];
                  updated[idx].checked = e.target.checked;
                  setNotasSelecionadas(updated);
                }}
              />
            </td>
            <td className="p-2 border">{nota.nf}</td>
            <td className="p-2 border">{nota.remetente}</td>
            <td className="p-2 border">{nota.pedido}</td>
            <td className="p-2 border">{nota.peso}</td>
            <td className="p-2 border">{nota.valor}</td>
          </tr>
        ))}
      </tbody>
    </table>

    <div className="text-right mt-2">
      <button
        onClick={() => {
          const filtradas = notasSelecionadas.filter(nota => !nota.checked);
          setNotasSelecionadas(filtradas);
        }}
        className="mt-2 bg-red-600 text-white px-4 py-1 rounded hover:bg-red-700 text-sm"
      >
        Remover Selecionadas
      </button>
    </div>
  </div>
)}

            <div className="text-right">
              <button
                onClick={() => {
                  setShowNotaModal(false);
                  setNotas([]);
                  setFiltroNota("");
                }}
                className="mt-4 text-sm text-gray-500 hover:underline"
              >
                Fechar
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Modal da Ordem de Serviço para impressão */}
      {showOrdemModal && dadosOrdem && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white p-6 rounded-xl w-full max-w-4xl shadow-xl space-y-4 relative">
            <button
              onClick={() => setShowOrdemModal(false)}
              className="absolute top-2 right-2 text-xl font-bold"
            >
              &times;
            </button>
            <OrdemDeColetaPrint dados={dadosOrdem} />
            <div className="text-right mt-4">
              <button
                onClick={() => window.print()}
                className="bg-blue-600 text-white px-6 py-2 rounded hover:bg-blue-700"
              >
                Imprimir
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
