
import IndexURI from '../api/index';
import { buscarDadosPublico } from '../api/ApiBaseService';
import { Usuario, UsuarioAPI } from '../models/Usuario';
import { SeVazioUndefinedOuNulo } from '../utilities/Utilidades';
import { errorMessage } from '../components/Mensagem';

export class UsuarioServico {

    static async Login(usuario) {
        let resposta

        try {

            return resposta = await buscarDadosPublico(
                IndexURI().login_uri,
                'POST',
                usuario
            );


        } catch (error) {
            console.log(error);
            resposta.erros = error;
            resposta.sucesso = false;
        }
        finally {
            return resposta;
        }
    }
}