import React, { useState, useEffect } from "react";

const carreteirosMock = [
  { id: 1, nome: "Carlos Eduardo" },
  { id: 2, nome: "Paulo Henrique" },
  { id: 3, nome: "João Caminhoneiro" },
];

const coletasMock = [
  { id: 1, data: "2025-07-01", motivo: "Devolução", loja: "Loja 1000", cliente: "Cliente X", carreteiroId: 1, status: "Pendente" },
  { id: 2, data: "2025-07-02", motivo: "Reentrega", loja: "Loja 1001", cliente: "Cliente Y", carreteiroId: 2, status: "Aprovado" },
  { id: 3, data: "2025-07-03", motivo: "Coleta", loja: "Loja 1027", cliente: "Cliente Z", carreteiroId: 3, status: "Aprovado" },
];

// Utilitário para formatar data
const formatDate = (iso) => {
  const d = new Date(iso);
  return d.toLocaleDateString("pt-BR");
};

export default function ListaColetas() {
  const [filtroMotivo, setFiltroMotivo] = useState("");
  const [filtroInicio, setFiltroInicio] = useState("");
  const [filtroFim, setFiltroFim] = useState("");
  const [filtroStatus, setFiltroStatus] = useState("");
  const [coletas, setColetas] = useState([]);

  useEffect(() => {
    const coletasComNomes = coletasMock.map(coleta => {
      const carreteiro = carreteirosMock.find(c => c.id === coleta.carreteiroId);
      return {
        ...coleta,
        nomeCarreteiro: carreteiro ? carreteiro.nome : "N/A"
      };
    });
    setColetas(coletasComNomes);
  }, []);

  const coletasFiltradas = coletas.filter((c) => {
    const dentroPeriodo =
      (!filtroInicio || new Date(c.data) >= new Date(filtroInicio)) &&
      (!filtroFim || new Date(c.data) <= new Date(filtroFim));
    const motivoCond = !filtroMotivo || c.motivo === filtroMotivo;
    const statusCond = !filtroStatus || c.status === filtroStatus;
    return dentroPeriodo && motivoCond && statusCond;
  });

  return (
    <div className="p-4">
      <h2 className="text-xl font-bold mb-4">Lista de Coletas</h2>

      {/* Filtros */}
      <div className="flex gap-4 mb-4">
        <div>
          <label className="block text-sm">Início</label>
          <input
            type="date"
            value={filtroInicio}
            onChange={(e) => setFiltroInicio(e.target.value)}
            className="border px-2 py-1 rounded"
          />
        </div>
        <div>
          <label className="block text-sm">Fim</label>
          <input
            type="date"
            value={filtroFim}
            onChange={(e) => setFiltroFim(e.target.value)}
            className="border px-2 py-1 rounded"
          />
        </div>
        <div>
          <label className="block text-sm">Motivo</label>
          <select
            value={filtroMotivo}
            onChange={(e) => setFiltroMotivo(e.target.value)}
            className="border px-2 py-1 rounded"
          >
            <option value="">Todos</option>
            <option value="Devolução">Devolução</option>
            <option value="Reentrega">Reentrega</option>
            <option value="Entrega">Entrega</option>
            <option value="Coleta">Coleta</option>
          </select>
        </div>
        <div>
          <label className="block text-sm">Status</label>
          <select
            value={filtroStatus}
            onChange={(e) => setFiltroStatus(e.target.value)}
            className="border px-2 py-1 rounded"
          >
            <option value="">Todos</option>
            <option value="Pendente">Pendente</option>
            <option value="Aprovado">Aprovado</option>
          </select>
        </div>
      </div>

      {/* Tabela */}
      <table className="min-w-full bg-white border">
        <thead>
          <tr className="bg-gray-100">
            <th className="border px-4 py-2">Nº Coleta</th>
            <th className="border px-4 py-2">Data</th>
            <th className="border px-4 py-2">Motivo</th>
            <th className="border px-4 py-2">Loja</th>
            <th className="border px-4 py-2">Remetente</th>
            <th className="border px-4 py-2">Carreteiro</th>
            <th className="border px-4 py-2">Status</th>
          </tr>
        </thead>
        <tbody>
          {coletasFiltradas.map((coleta) => (
            <tr key={coleta.id}>
              <td className="border px-4 py-2">{String(coleta.id).padStart(6, "0")}</td>
              <td className="border px-4 py-2">{formatDate(coleta.data)}</td>
              <td className="border px-4 py-2">{coleta.motivo}</td>
              <td className="border px-4 py-2">{coleta.loja}</td>
              <td className="border px-4 py-2">{coleta.cliente}</td>
              <td className="border px-4 py-2">{coleta.nomeCarreteiro}</td>
              <td className="border px-4 py-2">
                <span
                  className={`text-sm font-semibold ${
                    coleta.status === "Pendente" ? "text-red-600" : "text-green-600"
                  }`}
                >
                  {coleta.status}
                </span>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
