import { useState, useEffect } from 'react';

import {
    errorMessage
} from '../components/Mensagem';

import {
    fetchingDataLoading, stopFetchingDataLoading
} from '../components/Loading';
import { SeVazioUndefinedOuNulo } from '../utilities/Utilidades';


export const buscarDadosPublico = async (url, method, body = null) => {
    return buscarDados(url, method, body);
};

export const buscarDadosPrivado = async (url, method, body = null, token) => {
    if (!token) throw new Error('Authentication token is required');
    return buscarDados(url, method, body, token);
};

//function to handle API requests
const buscarDados = async (url, method, body = null, token = null) => {

    let resposta;
    let respostaTexto;
    let data = { status: null, sucesso: true, mensagem: null, erros: null, data: null };

    var options = {
        method: method,
    };

    if (body) options.body = JSON.stringify(body);

    try {
        fetchingDataLoading();

        resposta = await fetch(url, {
            ...options,
            headers: {
                'Content-Type': 'application/json',
                ...(token ? { 'Authorization': `Bearer ${token}` } : {})
            }
        });

        respostaTexto = await resposta.text();

        data.status = resposta.status;

        //Erro na API <> 200
        if (data.status !== 200) {
            data.sucesso = false;
            data.mensagem = respostaTexto;
            data.erros = data.mensagem;
            console.log(data.mensagem);
            return data;
        }

        //Resposta retorna vazia
        if (data.status == 200 && SeVazioUndefinedOuNulo(respostaTexto)) {
            return data;
        }

        //Se o retorno for um JSON válido
        try {
            data.data = JSON.parse(respostaTexto);
        } catch (jsonError) {
            console.error('JSON parse error:', jsonError);
            data.erros = 'Invalid JSON resposta';
        }

        console.log(data);
        return data;

    } catch (error) {
        console.error('Fetch error:', error);
    } finally {
        stopFetchingDataLoading();
        options = null;
        body = null;
        respostaTexto = null;
    }
}