import React, { useState } from 'react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
} from 'recharts';
import * as XLSX from 'xlsx';
import { saveAs } from 'file-saver';

const lojas = [
  { codigo: 1000, nome: 'Leo CD' },
  { codigo: 1001, nome: 'Leo Madeiras Gasometro' },
  { codigo: 1003, nome: 'Leo Madeiras Paes Leme' },
  { codigo: 1006, nome: 'Santos' },
  { codigo: 1007, nome: 'São José dos Campos' },
  { codigo: 1008, nome: 'Sampaio' },
  { codigo: 1011, nome: 'Leo Madeiras Aricanduva' },
  { codigo: 1016, nome: 'Leo Madeiras Lapa' },
  { codigo: 1027, nome: 'S.J. do Rio Preto' }
];

const dadosMargemPorLoja = lojas.map((loja) => {
  const valorPago = parseFloat((Math.random() * 5000 + 1000).toFixed(2));
  const valorCobrado = parseFloat((valorPago * (Math.random() * 0.5 + 0.75)).toFixed(2));
  const pesoTotal = parseFloat((Math.random() * 1000 + 200).toFixed(2));
  const receitaTotal = parseFloat((Math.random() * 20000 + 3000).toFixed(2));
  const totalNotas = Math.floor(Math.random() * 20 + 5);
  const diferenca = parseFloat((valorCobrado - valorPago).toFixed(2));
  const percentual = ((diferenca / valorPago) * 100).toFixed(2);
  const cabecalho = `${Math.floor(Math.random() * 110 + 1)}`.padStart(2, '0');

  return {
    codigoLoja: loja.codigo,
    nomeLoja: loja.nome,
    valorPago,
    valorCobrado,
    diferenca,
    percentual,
    pesoTotal,
    receitaTotal,
    totalNotas,
    cabecalho
  };
});

const dadosPorMes = Array.from({ length: 12 }, (_, i) => ({
  mes: `${i + 1}`.padStart(2, '0'),
  valor: parseFloat((Math.random() * 20000 + 3000).toFixed(2))
}));

export default function Lojas() {
  const [dataInicio, setDataInicio] = useState('');
  const [dataFim, setDataFim] = useState('');
  const [cabecalhoFiltro, setCabecalhoFiltro] = useState('');
  const [lojaSelecionadaMargem, setLojaSelecionadaMargem] = useState(null);

  const cabecalhosFiltrados = cabecalhoFiltro
    .split(',')
    .map(c => c.trim())
    .filter(c => c);

  const dadosFiltrados = dadosMargemPorLoja.filter((item) => {
    if (cabecalhosFiltrados.length === 0) return true;
    return cabecalhosFiltrados.includes(item.cabecalho);
  });

  const exportarExcel = () => {
    const worksheet = XLSX.utils.json_to_sheet(dadosFiltrados.map(item => ({
      'Código Loja': item.codigoLoja,
      'Nome Loja': item.nomeLoja,
      'Cabeçalho': item.cabecalho,
      'Peso Total': item.pesoTotal,
      'Receita': item.receitaTotal,
      'Total de Notas': item.totalNotas,
      'Frete Transportador': item.valorPago,
      'Frete Loja': item.valorCobrado,
      'Diferença': item.diferenca,
      '%': item.percentual
    })));

    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Margem por Loja');
    const excelBuffer = XLSX.write(workbook, { bookType: 'xlsx', type: 'array' });
    saveAs(new Blob([excelBuffer], { type: 'application/octet-stream' }), 'margem_por_loja.xlsx');
  };

  return (
    <div className="p-4 space-y-4">
      {/* Filtros */}
      <div className="flex flex-wrap gap-4 mb-4">
        <div>
          <label className="block text-sm">Início</label>
          <input
            type="date"
            value={dataInicio}
            onChange={(e) => setDataInicio(e.target.value)}
            className="border px-2 py-1 rounded"
          />
        </div>
        <div>
          <label className="block text-sm">Fim</label>
          <input
            type="date"
            value={dataFim}
            onChange={(e) => setDataFim(e.target.value)}
            className="border px-2 py-1 rounded"
          />
        </div>
        <div>
          <label className="block text-sm">Cabeçalho (vários separados por vírgula)</label>
          <input
            type="text"
            value={cabecalhoFiltro}
            onChange={(e) => setCabecalhoFiltro(e.target.value)}
            placeholder="Ex: 01, 22, 105"
            className="border px-2 py-1 rounded w-48"
          />
        </div>
        <div className="flex items-end">
          <button
            onClick={exportarExcel}
            className="bg-green-600 text-white px-4 py-1 rounded hover:bg-green-700"
          >
            Exportar Excel
          </button>
        </div>
      </div>

      {/* Tabela */}
      <div className="bg-white p-4 rounded shadow">
        <h2 className="text-xl font-semibold mb-4">Margem por Loja (Período Selecionado)</h2>
        <div className="overflow-auto max-h-96">
          <table className="w-full text-left border-collapse text-sm">
            <thead>
              <tr>
                <th className="p-2">Código Loja</th>
                <th className="p-2">Nome Loja</th>
                <th className="p-2">Cabeçalho</th>
                <th className="p-2">Peso Total</th>
                <th className="p-2">Receita</th>
                <th className="p-2">Total de Notas</th>
                <th className="p-2">Frete Transportador</th>
                <th className="p-2">Frete Loja</th>
                <th className="p-2">Diferença</th>
                <th className="p-2">%</th>
              </tr>
            </thead>
            <tbody>
              {dadosFiltrados.map((item) => (
                <tr
                  key={item.codigoLoja}
                  className={`cursor-pointer hover:bg-green-100 ${lojaSelecionadaMargem === item.codigoLoja ? 'bg-green-200 font-bold' : ''}`}
                  onClick={() => setLojaSelecionadaMargem(item.codigoLoja)}
                >
                  <td className="p-2">{item.codigoLoja}</td>
                  <td className="p-2">{item.nomeLoja}</td>
                  <td className="p-2">{item.cabecalho}</td>
                  <td className="p-2">{item.pesoTotal} kg</td>
                  <td className="p-2">R$ {item.receitaTotal.toFixed(2)}</td>
                  <td className="p-2">{item.totalNotas}</td>
                  <td className="p-2">R$ {item.valorPago.toFixed(2)}</td>
                  <td className="p-2">R$ {item.valorCobrado.toFixed(2)}</td>
                  <td className={`p-2 ${item.diferenca >= 0 ? 'text-green-600' : 'text-red-600'}`}>
                    {item.diferenca >= 0 ? '▲' : '▼'} R$ {item.diferenca.toFixed(2)}
                  </td>
                  <td className={`p-2 ${item.percentual >= 0 ? 'text-green-600' : 'text-red-600'}`}>
                    {item.percentual}%
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Gráfico por loja */}
      <div className="bg-white p-4 rounded shadow h-[400px] flex flex-col">
        <h2 className="font-bold mb-2">Valor Frete Por Loja (Gráfico de Barras)</h2>
        <ResponsiveContainer width="100%" height="100%">
          <BarChart
            data={dadosFiltrados}
            margin={{ top: 20, right: 30, left: 20, bottom: 40 }}
          >
            <CartesianGrid strokeDasharray="3 3" />
            <XAxis dataKey="codigoLoja" />
            <YAxis />
            <Tooltip formatter={(value) => `R$ ${value.toFixed(2)}`} />
            <Bar dataKey="valorPago" fill="#28a745" name="Valor Pago" />
          </BarChart>
        </ResponsiveContainer>
      </div>

      {/* Gráfico por mês */}
      <div className="bg-white p-4 rounded shadow h-[400px] flex flex-col">
        <h2 className="font-bold mb-2">Valor Frete Por Mês - Todas as Lojas</h2>
        <ResponsiveContainer width="100%" height="100%">
          <BarChart
            data={dadosPorMes}
            margin={{ top: 20, right: 30, left: 20, bottom: 40 }}
          >
            <CartesianGrid strokeDasharray="3 3" />
            <XAxis dataKey="mes" />
            <YAxis />
            <Tooltip formatter={(value) => `R$ ${value.toFixed(2)}`} />
            <Bar dataKey="valor" fill="#dc3545" name="Valor Total" />
          </BarChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}
